B.cl7=new A.jj(B.bxU,B.bFL,B.bTu,B.b4o,B.Yy)
B.bwB=new A.e("\u0423\u0432\u0435\u0440\u0435\u043d\u043d\u043e\u0441\u0442\u044c \u0432 \u0442\u043e\u043c, \u0447\u0442\u043e \u0442\u0432\u043e\u044f \u0436\u0438\u0437\u043d\u044c \u043d\u0430\u043f\u043e\u043b\u043d\u0435\u043d\u0430 \u0432\u0430\u0436\u043d\u044b\u043c\u0438 \u043e\u0440\u0438\u0435\u043d\u0442\u0438\u0440\u0430\u043c\u0438, \u0438\u043c\u0435\u0435\u0442 \u0446\u0435\u043d\u043d\u043e\u0441\u0442\u044c \u0438 \u0443\u043d\u0438\u043a\u0430\u043b\u044c\u043d\u043e\u0435 \u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u0435.","The confidence that your life is filled with important guideposts, has value, and holds a unique direction.")
B.bJF=new A.e("\u041a\u0435\u0434\u0440 \u0438\u0441\u0442\u0438\u043d\u043d\u043e\u0433\u043e \u0441\u043c\u044b\u0441\u043b\u0430 \u0443\u043a\u0440\u0435\u043f\u043b\u044f\u0435\u0442\u0441\u044f, \u043a\u043e\u0433\u0434\u0430 \u0442\u044b \u0443\u0447\u0438\u0448\u044c\u0441\u044f \u043e\u0441\u043c\u044b\u0441\u043b\u044f\u0442\u044c \u0441\u0432\u043e\u0439 \u043e\u043f\u044b\u0442, \u043d\u0430\u0445\u043e\u0434\u0438\u0442\u044c \u0443\u0440\u043e\u043a\u0438 \u0432 \u0442\u0440\u0443\u0434\u043d\u043e\u0441\u0442\u044f\u0445 \u0438 \u0434\u0435\u0439\u0441\u0442\u0432\u043e\u0432\u0430\u0442\u044c \u0440\u0430\u0434\u0438 \u0432\u0430\u0436\u043d\u043e\u0433\u043e. \u041e\u043d\u043e \u0437\u0430\u0449\u0438\u0449\u0430\u0435\u0442 \u043e\u0442 \u044d\u043a\u0437\u0438\u0441\u0442\u0435\u043d\u0446\u0438\u0430\u043b\u044c\u043d\u043e\u0439 \u0442\u0440\u0435\u0432\u043e\u0433\u0438, \u0434\u0430\u0432\u0430\u044f \u0443\u0441\u0442\u043e\u0439\u0447\u0438\u0432\u044b\u0439 \u0432\u043d\u0443\u0442\u0440\u0435\u043d\u043d\u0438\u0439 \u043a\u043e\u043c\u043f\u0430\u0441.","The Cedar of True Meaning strengthens when you learn to make sense of your experience, find lessons in hardships, and act for the sake of what matters. It protects against existential anxiety, offering a steady inner compass.")
B.bPQ=new A.e("\u0418\u0441\u0441\u043b\u0435\u0434\u043e\u0432\u0430\u043d\u0438\u044f \u043e\u0441\u043c\u044b\u0441\u043b\u0435\u043d\u043d\u043e\u0441\u0442\u0438 \u0436\u0438\u0437\u043d\u0438 \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0430\u044e\u0442, \u0447\u0442\u043e \u043d\u0430\u043b\u0438\u0447\u0438\u0435 \u044f\u0441\u043d\u044b\u0445 \u0446\u0435\u043d\u043d\u043e\u0441\u0442\u043d\u044b\u0445 \u043e\u0440\u0438\u0435\u043d\u0442\u0438\u0440\u043e\u0432 \u0437\u043d\u0430\u0447\u0438\u0442\u0435\u043b\u044c\u043d\u043e \u0441\u043d\u0438\u0436\u0430\u0435\u0442 \u0440\u0438\u0441\u043a \u0434\u0435\u043f\u0440\u0435\u0441\u0441\u0438\u0438 \u0438 \u043f\u043e\u0432\u044b\u0448\u0430\u0435\u0442 \u0432\u043d\u0443\u0442\u0440\u0435\u043d\u043d\u044e\u044e \u043c\u043e\u0442\u0438\u0432\u0430\u0446\u0438\u044e.","Research into the meaningfulness of life confirms that having clear value-based guidelines significantly reduces the risk of depression and boosts inner motivation.")
B.bFV=new A.e("\u0422\u044b \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u0435\u0448\u044c \u0440\u0435\u0448\u0435\u043d\u0438\u044f, \u0441\u0432\u0435\u0440\u044f\u044f\u0441\u044c \u0441\u043e \u0441\u0432\u043e\u0438\u043c\u0438 \u0432\u043d\u0443\u0442\u0440\u0435\u043d\u043d\u0438\u043c\u0438 \u0446\u0435\u043d\u043d\u043e\u0441\u0442\u044f\u043c\u0438, \u0430 \u043d\u0435 \u0441 \u043c\u043e\u0434\u043e\u0439.","You make decisions by checking in with your inner values, rather than what is fashionable.")
B.bDI=new A.e("\u0414\u0430\u0436\u0435 \u0432 \u0442\u044f\u0436\u0435\u043b\u044b\u0435 \u0434\u043d\u0438 \u0442\u044b \u043f\u043e\u043d\u0438\u043c\u0430\u0435\u0448\u044c, \u0440\u0430\u0434\u0438 \u0447\u0435\u0433\u043e \u0441\u0442\u043e\u0438\u0442 \u043f\u0440\u043e\u0441\u044b\u043f\u0430\u0442\u044c\u0441\u044f \u043f\u043e \u0443\u0442\u0440\u0430\u043c.","Even on hard days, you understand what makes it worth waking up in the morning.")
B.bRB=new A.e("\u0422\u0435\u0431\u0435 \u043d\u0440\u0430\u0432\u0438\u0442\u0441\u044f \u043f\u043e\u0434\u0434\u0435\u0440\u0436\u0438\u0432\u0430\u0442\u044c \u0434\u0440\u0443\u0433\u0438\u0445 \u0438 \u0432\u043d\u043e\u0441\u0438\u0442\u044c \u0441\u0432\u043e\u0439 \u043f\u043e\u0441\u0438\u043b\u044c\u043d\u044b\u0439 \u0432\u043a\u043b\u0430\u0434 \u0432 \u043c\u0438\u0440 \u0432\u043e\u043a\u0440\u0443\u0433.","You enjoy supporting others and making your own modest contribution to the world around you.")
