B.bPF=new A.e("\u0414\u0435\u0440\u0435\u0432\u043e \u041f\u0440\u0438\u043d\u044f\u0442\u0438\u044f","The Tree of Acceptance")
B.bPA=new A.e("\u041f\u0440\u0438\u043d\u044f\u0442\u0438\u0435","Acceptance")
B.bNN=new A.e("\u0412\u0441\u0435\u043c\u0443 \u0441\u0432\u043e\u0451 \u043c\u0435\u0441\u0442\u043e","Everything has its place")
B.bNe=new A.e(u.jW,"Accepting reality frees up energy for change.")
B.bsM=new A.e("\u0414\u0435\u0440\u0435\u0432\u043e \u041e\u0431\u0438\u0434\u044b","The Tree of Resentment")
