B.bMG=new A.e("\u0412\u0441\u0451 \u043d\u0435 \u0437\u0440\u044f","It's all worth it")
B.bLN=new A.e(u.p6,"My life has value, direction, and deep meaning.")
B.bJM=new A.e("\u0414\u0435\u0440\u0435\u0432\u043e \u041f\u0443\u0441\u0442\u043e\u0442\u044b","The Tree of Emptiness")
B.bMY=new A.e("\u041f\u0443\u0441\u0442\u043e\u0442\u0430","Emptiness")
B.bst=new A.e("\u0417\u0430\u0447\u0435\u043c \u0432\u0441\u0451 \u044d\u0442\u043e","What is it all for")
