B.bCO=new A.e("\u041c\u043e\u0438 \u043c\u0430\u043b\u0435\u043d\u044c\u043a\u0438\u0435 \u043f\u043e\u0431\u0435\u0434\u044b \u0441\u0447\u0438\u0442\u0430\u044e\u0442\u0441\u044f","My small victories count")
B.bOT=new A.e("\u042f \u043d\u0435\u0434\u043e\u0441\u0442\u0430\u0442\u043e\u0447\u043d\u043e {\u0445\u043e\u0440\u043e\u0448|\u0445\u043e\u0440\u043e\u0448\u0430}","I am not good enough")
B.btF=new A.e("\u0421\u043a\u043e\u0440\u043e \u0432\u0441\u0435 \u043f\u043e\u0439\u043c\u0443\u0442, \u0447\u0442\u043e \u044f \u043d\u0438\u0447\u0435\u0433\u043e \u043d\u0435 \u0441\u0442\u043e\u044e","Soon everyone will realize I'm worthless")
B.buT=new A.e("\u041c\u043e\u0438 \u043d\u0443\u0436\u0434\u044b \u2014 \u043f\u043e\u0442\u043e\u043c","My needs come last")
B.bF6=new A.e("\u041b\u0438\u0431\u043e \u0438\u0434\u0435\u0430\u043b\u044c\u043d\u043e, \u043b\u0438\u0431\u043e \u043d\u0438\u043a\u0430\u043a","Either perfect or nothing at all")
B.bvV=new A.e("\u042f \u043c\u043e\u0433\u0443 \u043f\u043e\u043f\u0440\u043e\u0441\u0438\u0442\u044c \u043e \u043f\u043e\u043c\u043e\u0449\u0438","I can ask for help")
B.bKP=new A.e("\u041d\u0430\u043f\u043e\u043c\u043d\u0438\u0442\u044c \u043e \u0441\u0435\u0431\u0435 \u2014 \u043d\u043e\u0440\u043c\u0430\u043b\u044c\u043d\u043e","It's okay to remind people about myself")
B.bwJ=new A.e("\u0411\u043e\u043b\u044c\u0448\u0438\u043d\u0441\u0442\u0432\u043e \u043b\u044e\u0434\u0435\u0439 \u043d\u0435 \u0436\u0435\u043b\u0430\u044e\u0442 \u043c\u043d\u0435 \u0437\u043b\u0430","Most people wish me no harm")
B.bAx=new A.e("\u0411\u0443\u0434\u0443\u0449\u0435\u0435 \u043c\u043e\u0436\u0435\u0442 \u0431\u044b\u0442\u044c \u0434\u043e\u0431\u0440\u044b\u043c","The future can be kind")
B.bz5=new A.e("\u041c\u0435\u043d\u044f \u0438\u0433\u043d\u043e\u0440\u0438\u0440\u0443\u044e\u0442 \u043d\u0430\u0440\u043e\u0447\u043d\u043e","I am being ignored on purpose")
B.bR1=new A.e("\u0412\u0441\u0435\u043c \u043e\u0442 \u043c\u0435\u043d\u044f \u0447\u0442\u043e-\u0442\u043e \u043d\u0443\u0436\u043d\u043e","Everyone wants something from me")
B.bLv=new A.e("\u041d\u0435 \u043f\u043e\u043a\u0430\u0437\u044b\u0432\u0430\u0439, \u0447\u0442\u043e \u0442\u0435\u0431\u0435 \u0432\u0430\u0436\u043d\u043e","Don't show what matters to you")
B.bNK=new A.e("\u0412\u043e\u0442-\u0432\u043e\u0442 \u0441\u043b\u0443\u0447\u0438\u0442\u0441\u044f \u0447\u0442\u043e-\u0442\u043e \u0441\u0442\u0440\u0430\u0448\u043d\u043e\u0435","Something terrible is about to happen")
B.bOp=new A.e("\u0428\u0430\u0433 \u0437\u0430 \u0448\u0430\u0433\u043e\u043c \u044f \u0441\u043f\u0440\u0430\u0432\u043b\u044e\u0441\u044c","Step by step, I will get through this")
B.bv2=new A.e("\u041c\u043e\u0436\u043d\u043e \u043f\u043e\u043f\u0440\u043e\u0431\u043e\u0432\u0430\u0442\u044c \u0438\u043d\u0430\u0447\u0435","I can try a different way")
B.bKR=new A.e("\u041a\u043e\u0435-\u0447\u0442\u043e \u0437\u0430\u0432\u0438\u0441\u0438\u0442 \u043e\u0442 \u043c\u0435\u043d\u044f","Some things depend on me")
B.bOr=new A.e("\u0423 \u043c\u0435\u043d\u044f \u043b\u0430\u043f\u043a\u0438","I'm just a little helpless creature")
B.bFM=new A.e("\u0412\u0441\u0451 \u0440\u0430\u0432\u043d\u043e \u043d\u0438\u0447\u0435\u0433\u043e \u043d\u0435 \u043f\u043e\u043b\u0443\u0447\u0438\u0442\u0441\u044f","It won't work out anyway")
