B.bKY=new A.e("\u0427\u0442\u043e \u044f \u043c\u043e\u0433\u0443 \u0441\u0434\u0435\u043b\u0430\u0442\u044c \u0441\u0435\u0439\u0447\u0430\u0441?","What can I do right now?")
B.bCq=new A.e(u.cQ,"Life isn't always fair, but I can keep living")
