B.bQm=new A.e("\u042f \u044d\u0442\u043e\u0433\u043e \u043d\u0438\u043a\u043e\u0433\u0434\u0430 \u043d\u0435 \u043f\u0440\u043e\u0449\u0443","I will never forgive this")
B.bC9=new A.e("\u0415\u0441\u043b\u0438 \u0431\u044b \u0442\u043e\u0433\u0434\u0430 \u0432\u0441\u0451 \u0431\u044b\u043b\u043e \u0438\u043d\u0430\u0447\u0435\u2026","If only everything had been different back then...")
B.bvP=new A.e("\u041c\u0435\u043d\u044f \u043c\u043e\u0436\u043d\u043e \u043b\u044e\u0431\u0438\u0442\u044c","I am lovable")
B.bNR=new A.e("\u0423 \u043a\u0430\u0436\u0434\u043e\u0433\u043e \u0435\u0441\u0442\u044c \u0441\u0432\u043e\u044f \u043f\u0440\u0438\u0447\u0438\u043d\u0430","Everyone has their own reason")
B.bHG=new A.e("\u041c\u043d\u0435 \u0435\u0441\u0442\u044c \u0437\u0430 \u0447\u0442\u043e \u0431\u043b\u0430\u0433\u043e\u0434\u0430\u0440\u0438\u0442\u044c","I have things to be grateful for")
B.bCX=new A.e("\u0427\u0443\u0436\u0430\u044f \u0440\u0430\u0434\u043e\u0441\u0442\u044c \u043d\u0435 \u043e\u0442\u043d\u0438\u043c\u0430\u0435\u0442 \u043c\u043e\u0435\u0439","Someone else's joy doesn't take away mine")
B.bPp=new A.e("\u0414\u043e\u043b\u0433\u0430\u044f \u0437\u043b\u043e\u0441\u0442\u044c \u0443\u0442\u043e\u043c\u043b\u044f\u0435\u0442, \u0430 \u0442\u0435\u043f\u043b\u043e \u043f\u0438\u0442\u0430\u0435\u0442","Holding onto anger is exhausting, but warmth feeds the soul")
B.bAm=new A.e("\u041c\u043d\u0435 \u0432\u0441\u0435 \u0434\u043e\u043b\u0436\u043d\u044b","Everyone owes me")
