B.b0Y=s([B.bAI,B.bw1,B.bNP],t.L)
B.bIC=new A.e("\u041c\u043e\u0439 \u0440\u043e\u0433 \u0441\u0432\u0435\u0442\u0438\u0442\u0441\u044f \u043d\u0435\u0436\u043d\u043e\u0441\u0442\u044c\u044e. \u042f \u043f\u0440\u0438\u0448\u0451\u043b \u0437\u0430\u043b\u0435\u0447\u0438\u0442\u044c \u0442\u0432\u043e\u0438 \u0440\u0430\u043d\u044b.","My horn glows with tenderness. I have come to heal your wounds.")
B.bDt=new A.e("\u0421\u0442\u0443\u043f\u0430\u0439 \u043c\u044f\u0433\u043a\u043e. \u0417\u0435\u043c\u043b\u044f \u043f\u043e\u0434 \u043c\u043e\u0438\u043c\u0438 \u043a\u043e\u043f\u044b\u0442\u0430\u043c\u0438 \u043d\u0430\u043f\u043e\u043b\u043d\u044f\u0435\u0442\u0441\u044f \u043f\u0440\u0438\u043d\u044f\u0442\u0438\u0435\u043c.","Walk softly. The earth beneath my hooves is filling with acceptance.")
B.bHx=new A.e("\u042f \u0445\u0440\u0430\u043d\u044e \u0447\u0438\u0441\u0442\u043e\u0442\u0443 \u0442\u0432\u043e\u0438\u0445 \u043f\u0435\u0440\u0432\u044b\u0445, \u0441\u0430\u043c\u044b\u0445 \u0434\u043e\u0431\u0440\u044b\u0445 \u0434\u0435\u0442\u0441\u043a\u0438\u0445 \u0432\u043e\u0441\u043f\u043e\u043c\u0438\u043d\u0430\u043d\u0438\u0439.","I keep safe the purity of your first, most gentle childhood memories.")
B.aNh=s([B.bIC,B.bDt,B.bHx],t.L)
B.bPe=new A.e("\u041c\u043e\u0438 \u0448\u0430\u0433\u0438 \u0442\u044f\u0436\u0451\u043b\u044b\u0435, \u043d\u043e \u043c\u044f\u0433\u043a\u0438\u0435. \u042f \u043d\u0435\u0441\u0443 \u0432 \u044d\u0442\u043e\u0442 \u043c\u0438\u0440 \u0442\u043e\u043d\u043d\u044b \u0443\u044e\u0442\u0430.","My steps are heavy yet soft. I bring tons of coziness into this world.")
